package com.swir.stream;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public final class PlaylistSuggestionsTest {
    private Station station(String name,String country,String url){Station s=new Station();s.name=name;s.country=country;s.url=url;return s;}
    private CatalogRepository.FoundPlaylist playlist(String source){CatalogRepository.FoundPlaylist p=new CatalogRepository.FoundPlaylist();p.source=source;p.name="Publiczna";p.fetchedAt=123456;p.modifiedAt=123000;return p;}
    @Test public void queryCountryAndUniqueChannelsAreCountedWithoutChangingDates(){CatalogRepository.FoundPlaylist p=playlist("https://example.com/list.m3u");List<Station> stations=Arrays.asList(station("TVP 1","PL","https://example.com/a"),station("TVP 1","PL","https://example.com/b"),station("TVP 2","PL","https://example.com/c"),station("TVP 1","DE","https://example.com/d"));PlaylistSuggestions.Entry e=PlaylistSuggestions.match(p,stations,"TVP 1",Collections.singleton("PL"),s->0);assertEquals(1,e.matches);assertEquals(4,e.total);assertEquals(123456,p.fetchedAt);assertEquals(123000,p.modifiedAt);assertNull(PlaylistSuggestions.match(p,stations,"missing",Collections.singleton("PL"),s->0));}
    @Test public void localPreferencesRankButNeverHideMatchingPlaylists(){CatalogRepository.FoundPlaylist a=playlist("https://a.example/list.m3u"),b=playlist("https://b.example/list.m3u");List<Station> stations=Collections.singletonList(station("News","PL","https://example.com/a"));PlaylistSuggestions.Entry first=PlaylistSuggestions.match(a,stations,"News",Collections.emptySet(),s->0),second=PlaylistSuggestions.match(b,stations,"News",Collections.emptySet(),s->5);List<PlaylistSuggestions.Entry> entries=PlaylistSuggestions.rank(Arrays.asList(first,second));assertEquals(2,entries.size());assertSame(b,entries.get(0).playlist);assertEquals(2,PlaylistSuggestions.rank(Arrays.asList(first,PlaylistSuggestions.match(b,stations,"News",Collections.emptySet(),s->0))).size());}
    @Test public void credentialUrlNeverBecomesPublicSuggestion(){assertNull(PlaylistSuggestions.match(playlist("https://example.com/get.php?username=demo&password=secret"),Collections.singletonList(station("News","PL","https://example.com/a")),"News",Collections.emptySet(),s->1));}
    @Test public void freshCopyPrecedesHighlyRankedStaleCopyWithoutDroppingEither(){CatalogRepository.FoundPlaylist old=playlist("https://old.example/list.m3u"),fresh=playlist("https://fresh.example/list.m3u");fresh.fetchedAt=System.currentTimeMillis();fresh.modifiedAt=0;List<PlaylistSuggestions.Entry> result=PlaylistSuggestions.rank(Arrays.asList(new PlaylistSuggestions.Entry(old,20,20,100),new PlaylistSuggestions.Entry(fresh,1,1,0)));assertSame(fresh,result.get(0).playlist);assertEquals(2,result.size());assertEquals(123456,old.fetchedAt);}
}
